#include <stdio.h>
int maxOf(int a[], int n){
    int m=a[0], i;
    for(i=1;i<n;i++) if(a[i]>m) m=a[i];
    return m;
}
int main(void){
    int a[]={4,9,2,7}, n=4, i, sum=0;
    for(i=0;i<n;i++) sum+=a[i];
    printf("max=%d avg=%.2f\n",maxOf(a,n),(double)sum/n);
    return 0;
}

